  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary/hs",
      "detail": "stdにある「それぞれ根拠となるルールが異なる。放送には法律の規定があり、新聞は業界の自主的な綱領を定めている」という重要な事実が欠落し、まったく異なる内容になっている。",
      "fix": "stdに合わせて、ニュースの種類ごとにルールが違うことや、放送には法律があり新聞には業界のルールがあることに書き直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text/hs",
      "detail": "stdは「新聞・テレビ・ネットのニュースには、それぞれどのようなルールが適用されているのでしょうか？」という問いかけだが、hsは「家に新聞がとどく家は、どれくらいあるのでしょう？」と全く関係のない内容になっている。",
      "fix": "stdに沿って、新聞・テレビ・ネットのニュースのルールに関する問いかけに書き直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/3/text/hs",
      "detail": "「※正確には、放送法は放送事業者を対象にした法律です。」という注釈的な文言が追加されているが、stdにはない補足や評価が含まれている。",
      "fix": "「※正確には〜」の注釈部分を削除する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/5/text/hs",
      "detail": "stdにある「1世帯当たり0.42部」という数値がhsから抜けている。",
      "fix": "1世帯当たりの部数についても記述を追加する。"
    }
  ]
}
